import axios from 'axios';

const axiosInstance = axios.create({
    baseURL: 'http://localhost:5000/api',
    withCredentials: true,
});

axiosInstance.interceptors.request.use(
    async (config) => {
        const token = localStorage.getItem('token');
        if (token) {
            config.headers['Authorization'] = `Bearer ${token}`;
        }
        return config;
    },
    
    (error) => Promise.reject(error)
);
 
axiosInstance.interceptors.response.use(
    (response) => response,
    async (error) => {
        if (error.response.status === 403 && !error.config._retry) {
            error.config._retry = true;

            try {
                const { data } = await axiosInstance.post('http://localhost:5000/api/auth/refresh-token', null);
                localStorage.setItem('token', data.accessToken); // Сохраняем новый токен
                error.config.headers['Authorization'] = `Bearer ${data.accessToken}`; // Обновляем заголовок
                return axiosInstance(error.config); // Повторяем запрос
            } catch (refreshError) {
                console.error('Ошибка при обновлении токена:', refreshError.response?.data?.message || refreshError.message);

                // Если обновление токена тоже вернуло 403, очищаем данные и перенаправляем пользователя
                if (refreshError.response && refreshError.response.status === 403) {
                    localStorage.clear(); // Очищаем хранилище
                    window.location.href = '/'; // Перенаправляем на страницу входа
                }

                return Promise.reject(refreshError); // Прокидываем ошибку дальше
            }
        }
        return Promise.reject(error);
    }
);

export default axiosInstance;
